// src/calculators/KTBundlingCalculator.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import KTBundlingForm from './KTBundlingForm';
import KTBundlingResult from './KTBundlingResult.jsx';


// 결합 메뉴 옵션 정의
const BUNDLE_OPTIONS = [
  { key: 'home', label: '홈 결합' },
  { key: 'family', label: '가족 결합' },
  { key: 'premium', label: '프리미엄 싱글결합' },
  { key: 'total', label: '총액 결합' },
  { key: 'special', label: '으랏차차 결합' },
  { key: 'smallbiz', label: '소상공인 결합' },
  { key: 'biz', label: 'Biz 결합' },
  { key: 'guide', label: '결합 안내' }
];

export default function KTBundlingCalculator() {
  const navigate = useNavigate();
  const [selectedOption, setSelectedOption] = useState(null);
  const [pricingData, setPricingData] = useState(null);
  const [formData, setFormData] = useState({ mobilePlan: '', internetPlan: '', tvPlan: '' });
  const [result, setResult] = useState(null);

  useEffect(() => {
    if (!selectedOption || selectedOption === 'guide') return;
    fetch(`/api/kt-bundling-pricing?type=${selectedOption}`)
      .then(res => res.json())
      .then(data => setPricingData(data))
      .catch(err => console.error('가격 데이터 로딩 오류:', err));
  }, [selectedOption]);

  const handleMenuClick = key => {
    setSelectedOption(key);
    setPricingData(null);
    setResult(null);
  };

  const handleCalculate = () => {
    if (!pricingData) return;
    const { mobilePlan, internetPlan, tvPlan } = formData;
    const mobilePrice = pricingData.mobile[mobilePlan]?.price || 0;
    const internetPrice = pricingData.internet[internetPlan]?.price || 0;
    const tvPrice = pricingData.tv[tvPlan]?.price || 0;
    const total = mobilePrice + internetPrice + tvPrice;
    const discountRate = pricingData.bundleDiscountRate || 0;
    const discountedTotal = Math.round(total * (1 - discountRate));
    setResult({ mobilePrice, internetPrice, tvPrice, total, discountRate, discountedTotal });
  };

  const handleBack = () => setSelectedOption(null);

  return (
    <div className="bg-gray-100 min-h-screen py-8">
      <div className="max-w-3xl mx-auto bg-white rounded-lg shadow-md overflow-hidden">
        {/* Header */}
        <div className="px-6 py-4 border-b">
          <h1 className="text-center text-xl font-bold">KT 결합 계산기</h1>
        </div>
        {/* Content */}
        <div className="p-6">
          {/* 메뉴 화면 */}
          {!selectedOption && (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
                {BUNDLE_OPTIONS.map(opt => (
                  <button
                    key={opt.key}
                    onClick={() => handleMenuClick(opt.key)}
                    className="bg-white hover:bg-gray-50 border rounded-lg py-3 shadow-sm transition"
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
              {/* 공지사항 */}
              <div className="mb-6">
                <h2 className="text-lg font-semibold mb-2">공지사항</h2>
                <div className="bg-gray-50 p-4 rounded">
                  <ul className="list-disc pl-5 space-y-1 text-sm text-gray-700">
                    <li>총영업 직원 여러분 환영합니다.</li>
                    <li>버튼을 클릭하여 원하는 계산기를 선택하세요.</li>
                    <li>오류나 개선 요청은 언제든 연락주세요.</li>
                    <li>2025.06.21 현재 '결합' 계산기는 시범 버전입니다.</li>
                  </ul>
                </div>
              </div>
              {/* 메인 메뉴 버튼 */}
              <button
                onClick={() => navigate('/')}
                className="w-full bg-white hover:bg-gray-50 border rounded-lg py-2 shadow-sm transition"
              >메인 메뉴로 돌아가기</button>
            </>
          )}

          {/* 결합 안내 화면 */}
          {selectedOption === 'guide' && (
            <>
              <h2 className="text-lg font-semibold mb-4">결합 안내</h2>
              <div className="bg-gray-50 p-4 rounded mb-6 text-gray-700">
                결합 안내 내용을 여기에 입력하세요.
              </div>
              <button
                onClick={handleBack}
                className="w-full bg-white hover:bg-gray-50 border rounded-lg py-2 shadow-sm transition"
              >메인 메뉴로 돌아가기</button>
            </>
          )}

          {/* 계산기 화면 */}
          {selectedOption && selectedOption !== 'guide' && (
            <>
              <h2 className="text-center font-semibold mb-4">
                {BUNDLE_OPTIONS.find(o => o.key === selectedOption).label} 할인 계산기
              </h2>
              <KTBundlingForm
                formData={formData}
                setFormData={setFormData}
                pricingData={pricingData}
                onCalculate={handleCalculate}
              />
              {result && <KTBundlingResult result={result} />}
              <button
                onClick={handleBack}
                className="mt-6 w-full bg-white hover:bg-gray-50 border rounded-lg py-2 shadow-sm transition"
              >메인 메뉴로 돌아가기</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}